#!/usr/bin/env bash
# Starts the demo profile (synthetic data, never production). Creates .env.demo with random
# secrets the first time; never reads the developer's .env.
set -euo pipefail
cd "$(dirname "$0")/../.."
if [ ! -f .env.demo ]; then
  secret() { openssl rand -hex "${1:-32}"; }
  umask 077
  cat > .env.demo <<ENV
# Generated by pnpm demo:up for the demo profile only. Synthetic data; do not reuse elsewhere.
POSTGRES_USER=tracop_demo
POSTGRES_PASSWORD=$(secret 24)
POSTGRES_DB=tracop_demo
MINIO_ROOT_USER=tracop-demo-$(secret 4)
MINIO_ROOT_PASSWORD=$(secret 24)
JWT_SECRET=$(secret 32)
OTP_HMAC_SECRET=$(secret 32)
RATE_LIMIT_HMAC_SECRET=$(secret 32)
METRICS_TOKEN=$(secret 32)
PRIVACY_POLICY_VERSION=v0-draft
ENV
  echo "Created .env.demo with random secrets."
fi
mkdir -p backups
docker compose -f docker-compose.demo.yml --env-file .env.demo up -d --build --wait api worker storage backup
echo "Demo up: API on http://${DEMO_BIND:-127.0.0.1}:${DEMO_API_PORT:-3100}, S3 on http://${DEMO_BIND:-127.0.0.1}:${DEMO_S3_PORT:-9100}."
echo "OTP codes are captured in a private file of the API container (OTP_SENDER=demo_capture), never logged:"
echo "  docker compose -f docker-compose.demo.yml --env-file .env.demo exec api cat /run/tracop-otp/codes.jsonl"
echo "Walk the whole flow with: pnpm demo:smoke"
